<script setup lang="ts">import {computed} from "vue";import type {VersionSummaryViewModel} from "~/types/account-version-summary";import StorySlideShell from "../StorySlideShell.vue";const p=defineProps<{summary:VersionSummaryViewModel;pageIndex:number;pageTotal:number;active:boolean;reducedMotion:boolean}>();const max=computed(()=>Math.max(...(p.summary.timeOfDay?.hourlyCounts||[1]),1));</script>
<template><StorySlideShell :page-index="pageIndex" :page-total="pageTotal" :eyebrow="summary.copy.timeOfDay.eyebrow" :title="summary.copy.timeOfDay.title" :lead="summary.copy.timeOfDay.body" tone="aurora" :active="active" :reduced-motion="reducedMotion"><div v-if="summary.timeOfDay" class="time"><div class="clock" data-animate><div class="clock__ticks"><i v-for="(count,hour) in summary.timeOfDay.hourlyCounts" :key="hour" :class="{peak:hour===summary.timeOfDay.favoriteHour}" :style="{'--turn':`${hour*15}deg`,'--size':Math.max(.16,count/max)}"><b></b></i></div><div class="clock__center"><span>最活跃时段</span><strong>{{summary.timeOfDay.favoriteHourLabel}}</strong><small>{{summary.timeOfDay.favoriteSong?.name||summary.timeOfDay.topLabel}}</small></div></div><div class="periods"><article v-for="period in summary.timeOfDay.periods" :key="period.key" :class="{top:period.key===summary.timeOfDay.topPeriod}" data-animate><span>{{period.label}} · {{period.range}}</span><strong>{{period.playCount}}</strong></article></div></div></StorySlideShell></template>
<style scoped>.time{height:100%;display:grid;grid-template-columns:minmax(220px,.72fr) 1fr;gap:12px}.clock,.periods article{border-radius:25px;background:#ffffff12;border:1px solid #ffffff1f}.clock{position:relative;display:grid;place-items:center;min-height:0}.clock__ticks{position:absolute;width:min(35vh,82%);aspect-ratio:1;border-radius:50%;border:1px solid #ffffff1a}.clock__ticks i{position:absolute;inset:0;transform:rotate(var(--turn));display:flex;justify-content:center}.clock__ticks b{display:block;width:3px;height:calc(8% + var(--size)*14%);border-radius:99px;background:linear-gradient(#6db9ff,#ff865d)}.clock__ticks i.peak b{width:5px;background:#ffe195;box-shadow:0 0 16px #ffc56f}.clock__center{z-index:1;width:56%;aspect-ratio:1;border-radius:50%;display:grid;place-content:center;text-align:center;background:#0e1f3ce8;border:1px solid #ffffff22;box-shadow:0 0 40px #5faeff22}.clock__center span,.clock__center small{color:#ffe6c499;font-size:9px}.clock__center strong{margin:5px 0;color:#fff8ed;font-size:clamp(1rem,2.5vw,1.7rem)}.periods{display:grid;grid-template-columns:repeat(2,1fr);gap:7px}.periods article{padding:11px;display:grid;align-content:center}.periods article.top{background:#ffb35f20;border-color:#ffd38a66}.periods span{color:#ffe6c499;font-size:9px}.periods strong{color:#fff8ed;font-size:1.25rem}@media(max-width:720px){.time{grid-template-columns:minmax(135px,.8fr) 1fr;gap:6px}.clock,.periods article{border-radius:15px}.clock__ticks{width:min(25vh,88%)}.clock__center strong{font-size:.78rem}.clock__center span,.clock__center small{font-size:6px}.periods{gap:4px}.periods article{padding:6px}.periods span{font-size:6px}.periods strong{font-size:.78rem}}</style>
